\section*{Preliminaries (Definitions and Lemmas)}

\begin{lemma}[Three‑point identity]\label{lem:3pt}
For any $x,y,z\in\R^{d}$,
\[
\Breg(x,z)=\Breg(x,y)+\Breg(y,z)+\langle \grad h(y)-\grad h(z),x-y\rangle .
\]
\end{lemma}

\begin{lemma}[Descent Lemma under relative smoothness]\label{lem:descent}
If $f$ satisfies Assumption \ref{as:smooth} and $0<\eta\le 1/L$, then for the update \eqref{eq:update}
\[
f(x_{k+1})\le f(x_{k})-\frac{\alpha}{2\eta}\|x_{k+1}-x_{k}\|^{2}.
\]
\end{lemma}
\begin{proof}
From optimality of $x_{k+1}$ we have
\[
\big\langle \grad f(x_{k})+\tfrac{1}{\eta}\big(\grad h(x_{k+1})-\grad h(x_{k})\big),\,x-x_{k+1}\big\rangle\ge0,
\qquad\forall x.
\]
Choose $x=x_{k}$ and rearrange:
\[
\langle \grad f(x_{k}),x_{k}-x_{k+1}\rangle\ge\frac{1}{\eta}\langle \grad h(x_{k+1})-\grad h(x_{k}),x_{k+1}-x_{k}\rangle .
\tag{A}
\]
Using strong convexity of $h$ (Assumption \ref{as:strong}),
\[
\langle \grad h(x_{k+1})-\grad h(x_{k}),x_{k+1}-x_{k}\rangle\ge\alpha\|x_{k+1}-x_{k}\|^{2}.
\tag{B}
\]
Insert (B) into (A):
\[
\langle \grad f(x_{k}),x_{k}-x_{k+1}\rangle\ge\frac{\alpha}{\eta}\|x_{k+1}-x_{k}\|^{2}.
\tag{C}
\]
Relative smoothness (Assumption \ref{as:smooth}) with $y=x_{k}$ and $x=x_{k+1}$ gives
\[
f(x_{k+1})\le f(x_{k})+\langle \grad f(x_{k}),x_{k+1}-x_{k}\rangle+L\Breg(x_{k+1},x_{k}).
\tag{D}
\]
Because $\Breg(x_{k+1},x_{k})\ge\frac{\alpha}{2}\|x_{k+1}-x_{k}\|^{2}$, and $\eta\le1/L$, we obtain
\[
L\Breg(x_{k+1},x_{k})\le\frac{1}{\eta}\Breg(x_{k+1},x_{k})
\le\frac{1}{2\eta}\alpha\|x_{k+1}-x_{k}\|^{2}.
\tag{E}
\]
Combine (C), (D) and (E):
\[
f(x_{k+1})\le f(x_{k})-\frac{\alpha}{\eta}\|x_{k+1}-x_{k}\|^{2}
+\frac{\alpha}{2\eta}\|x_{k+1}-x_{k}\|^{2}
= f(x_{k})-\frac{\alpha}{2\eta}\|x_{k+1}-x_{k}\|^{2}.
\]
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:main}.

\begin{proof}
Let $\eta_{k}\le 1/L$ and define the gradient mapping
\[
\mathcal{G}_{\eta_{k}}(x_{k})\;:=\;\frac{1}{\eta_{k}}(x_{k}-x_{k+1}).
\tag{1}\label{def:G}
\]

\noindent\textbf{[Step 1]}  Apply Lemma~\ref{lem:descent} with stepsize $\eta_{k}$:
\[
f(x_{k+1})\le f(x_{k})-\frac{\alpha}{2\eta_{k}}\|x_{k+1}-x_{k}\|^{2}
= f(x_{k})-\frac{\alpha\eta_{k}}{2}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}.
\tag{2}
\]

\noindent\textbf{[Step 2]}  Rearrange \eqref{2} to isolate the squared norm:
\[
\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}\le\frac{2}{\alpha\eta_{k}}\bigl(f(x_{k})-f(x_{k+1})\bigr).
\tag{3}
\]

\noindent\textbf{[Step 3]}  Sum \eqref{3} over $k=0,\dots,T-1$:
\[
\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}
\le\frac{2}{\alpha}\sum_{k=0}^{T-1}\frac{f(x_{k})-f(x_{k+1})}{\eta_{k}}.
\tag{4}
\]

\noindent\textbf{[Step 4]}  Since $\eta_{k}\le 1/L$, we have $1/\eta_{k}\ge L$. Hence
\[
\frac{1}{\eta_{k}}\le L\quad\Longrightarrow\quad
\frac{f(x_{k})-f(x_{k+1})}{\eta_{k}}
\le L\bigl(f(x_{k})-f(x_{k+1})\bigr).
\tag{5}
\]

\noindent\textbf{[Step 5]}  Insert \eqref{5} into \eqref{4}:
\[
\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}
\le\frac{2L}{\alpha}\sum_{k=0}^{T-1}\bigl(f(x_{k})-f(x_{k+1})\bigr)
= \frac{2L}{\alpha}\bigl(f(x_{0})-f(x_{T})\bigr).
\tag{6}
\]

\noindent\textbf{[Step 6]}  Drop the non‑negative term $f(x_{T})\ge f^{\inf}$:
\[
\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}
\le\frac{2L}{\alpha}\bigl(f(x_{0})-f^{\inf}\bigr).
\tag{7}
\]

\noindent\textbf{[Step 7]}  Divide both sides of \eqref{7} by $T$ to obtain the averaged bound:
\[
\frac{1}{T}\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}
\le\frac{2L}{\alpha T}\bigl(f(x_{0})-f^{\inf}\bigr).
\tag{8}
\]

\noindent\textbf{[Step 8]}  The minimum of a set of non‑negative numbers is bounded by its average, i.e.
\[
\min_{0\le k<T}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}
\le\frac{1}{T}\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}.
\tag{9}
\]
Combine \eqref{8} and \eqref{9} to obtain the final claim of the theorem.
\end{proof}

\section*{Rate Derivation (With Constants)}
From \eqref{8} we read off the explicit constant:
\[
C:=\frac{2L}{\alpha}\bigl(f(x_{0})-f^{\inf}\bigr).
\]
Thus for any $T\ge1$,
\[
\frac{1}{T}\sum_{k=0}^{T-1}\|\mathcal{G}_{\eta_{k}}(x_{k})\|^{2}\le\frac{C}{T},
\qquad
\min_{0\le k<T}\|\mathcal{G}_{\eta_{k}}(x_{k})\|\le\sqrt{\frac{C}{T}}.
\]

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Euclidean setting.} $h(x)=\tfrac12\|x\|^{2}$, $\alpha=1$, $\Breg(x,y)=\tfrac12\|x-y\|^{2}$. The gradient mapping reduces to the ordinary gradient step $\mathcal{G}_{\eta_{k}}(x_{k})=\grad f(x_{k})$, and Theorem~\ref{thm:main} recovers the classic $O(1/T)$ bound on $\|\grad f\|^{2}$ for smooth non‑convex functions.
\item \textbf{Probability simplex.} $h(x)=\sum_{i}x_{i}\log x_{i}$ (negative entropy). Here $\alpha=1$ w.r.t. the $\ell_{1}$ norm, and $\mathcal{G}_{\eta_{k}}$ corresponds to the multiplicative update used in exponentiated gradient methods.
\item \textbf{Strongly convex $f$.} If $f$ is additionally $\mu$‑strongly convex, one can combine Lemma~\ref{lem:descent} with the Polyak–Łojasiewicz inequality to obtain a linear convergence rate $O((1-\mu\eta)^{T})$.
\end{enumerate}

